func loadTables() *ts.Language {
	tables, err := ts.DecodeTables(tablesBlob)
	if err != nil {
		panic("bash: reading tables.zst: " + err.Error())
	}
	characterSets = tables.CharacterSets
	language := &tables.Language
	language.LexFn = tsLex
	language.KeywordLexFn = tsLexKeywords
	language.Scanner = scanner{}
	return language
}

func init() { load = loadTables }
